products = frappe.db.get_all(
    "Marsol Product",
    filters={
        "category": "Environmental Services"
    },
    fields=[
        "name",
        "product_name",
        "description",
        "product_image"
    ],
    limit_page_length=20
)

data.page_data = {
    "products": products
}

product_id = "dqqf5hkfi3"

product = frappe.get_doc(
    "Marsol Product",
    product_id
)

related_products = []

for row in product.related_products:

    related = frappe.get_doc(
        "Marsol Product",
        row.product
    )

    related_products.append({
        "name": related.name,
        "product_name": related.product_name,
        "description": related.description,
        "product_image": related.product_image,
        "category": related.category
    })


data.page_data = {
    "product": {
        "name": product.name,
        "product_name": product.product_name,
        "description": product.description,
        "product_image": product.product_image,
        "category": product.category
    },

    "related_products": related_products
}

